import net.minecraft.world.level.levelgen.structure.templatesystem.*;
import net.minecraft.world.phys.*;
/** Authored actual native registry/geometry/loot/Feature.place cases, all runtime UNRUN.
 * ServerLevel is a real WorldGenLevel; this is not proof of asynchronous natural FEATURES generation. */
public final class PaletteWorldgenGameTests {
    private static final String STRUCTURE="create_test:reservoir";
    private static final BlockPos P=new BlockPos(8,8,8);
    private static void stoneVolume(GameTestHelper h){for(var pos:BlockPos.betweenClosed(P.offset(-5,-5,-5),P.offset(5,5,5)))h.setBlock(pos,Blocks.STONE);var origin=h.absolutePos(P);h.assertTrue(h.getLevel().getHeight(Heightmap.Types.OCEAN_FLOOR_WG,origin.getX(),origin.getZ())>origin.getY(),"Actual native heightmap sees the real filled source generation volume");}
    private static LayeredOreFeature cinnabar(){return new LayeredOreFeature(new LayeredOreConfiguration(List.of(AllLayerPatterns.CINNABAR.get()),8,0));}
    private static net.minecraft.world.level.chunk.ChunkGenerator generator(GameTestHelper h){return h.getLevel().getChunkSource().getGenerator();}
    private static void withConfig(boolean disabled,Runnable body){try{var file=Files.createTempFile("create-native-worldgen-config-",".json");var original=CWorldGen.get();try{Files.writeString(file,"{\"disableWorldGen\":"+disabled+"}");CWorldGen.reload(file);body.run();}finally{Files.writeString(file,CWorldGen.Values.CODEC.encodeStart(JsonOps.INSTANCE,original).getOrThrow().toString());CWorldGen.reload(file);Files.delete(file);}}catch(java.io.IOException failure){throw new java.io.UncheckedIOException(failure);}}
    @GameTest(structure=STRUCTURE) public void all252NativeVariantsHaveExactOriginalIdsAndActualNativeShapeClasses(GameTestHelper h){h.assertValueEqual(AllPaletteStoneTypes.values().length,14,"All original14 stone families");h.assertValueEqual(PaletteStoneRegistry.blocks().size(),252,"All original252 actual variant singletons");var seen=new HashSet<String>();for(var stone:AllPaletteStoneTypes.values()){h.assertTrue(stone.getVariants().registeredBlocks.size()==6&&stone.getVariants().registeredPartials.size()==12,"Six source patterns and twelve real partials");String family=stone.name().toLowerCase(Locale.ROOT);for(var pattern:stone.variantTypes){String id=pattern.createName(family);var block=BuiltInRegistries.BLOCK.getValue(Create.asResource(id));h.assertTrue(block!=Blocks.AIR&&block.asItem()!=Items.AIR&&seen.add(id),"One real source block/item owner: "+id);}for(var block:stone.getVariants().registeredPartials)h.assertTrue(block instanceof StairBlock||block instanceof SlabBlock||block instanceof WallBlock,"Actual native shapes, not relabelled cubes");h.assertTrue(BuiltInRegistries.BLOCK.getValue(Create.asResource(family+"_pillar")) instanceof ConnectedPillarBlock,"Source real connected pillar");}h.assertValueEqual(BuiltInRegistries.BLOCK.getKey(AllBlocks.SCORCHIA),Create.asResource("scorchia"),"Original new raw stone ID");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceBasePropertiesKeepActualStoneSoundBlastAndOpaqueShape(GameTestHelper h){for(var block:List.of(AllBlocks.ASURINE,AllBlocks.CRIMSITE,AllBlocks.OCHRUM,AllBlocks.VERIDIUM,AllBlocks.LIMESTONE))h.assertValueEqual(block.defaultBlockState().getDestroySpeed(h.getLevel(),h.absolutePos(P)),1.25f,"Pinned hardness1.25");h.assertTrue(AllBlocks.ASURINE.defaultBlockState().getSoundType()==Blocks.DEEPSLATE.defaultBlockState().getSoundType()&&AllBlocks.OCHRUM.defaultBlockState().getSoundType()==Blocks.CALCITE.defaultBlockState().getSoundType()&&AllBlocks.SCORCHIA.defaultBlockState().getSoundType()==Blocks.BLACKSTONE.defaultBlockState().getSoundType(),"Original inherited native sounds");h.assertValueEqual(AllBlocks.ASURINE.getExplosionResistance(),Blocks.DEEPSLATE.getExplosionResistance(),"Pinned deepslate resistance survives destroyTime override");h.assertTrue(AllBlocks.ASURINE.defaultBlockState().canOcclude()&&AllBlocks.LIMESTONE.defaultBlockState().canOcclude(),"Source natural stones remain opaque native cubes");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceDoubleSlabLootProducesTwoRealOriginalSlabs(GameTestHelper h){var block=BuiltInRegistries.BLOCK.getValue(Create.asResource("polished_cut_scorchia_slab"));var state=block.defaultBlockState().setValue(SlabBlock.TYPE,net.minecraft.world.level.block.state.properties.SlabType.DOUBLE);h.setBlock(P,state);try(var f=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.east(3))))){var pick=new ItemStack(Items.DIAMOND_PICKAXE);var drops=Block.getDrops(state,h.getLevel(),h.absolutePos(P),null,f.player(),pick);h.assertValueEqual(drops.stream().filter(stack->stack.is(block.asItem())).mapToInt(ItemStack::getCount).sum(),2,"Actual native source slab loot pays two blocks for a real double slab");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void realPillarPlacementAlignsToOriginalColumnUntilActualSneakAndDebitsFiniteStock(GameTestHelper h){var block=BuiltInRegistries.BLOCK.getValue(Create.asResource("scorchia_pillar"));var support=P.below();h.setBlock(support,block.defaultBlockState().setValue(LayeredBlock.AXIS,Direction.Axis.Z));try(var f=NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P.east(3))))){var p=f.player();var stock=new ItemStack(block,3);stock.set(DataComponents.CUSTOM_NAME,Component.literal("Original native stone pillar stock"));p.setItemInHand(InteractionHand.MAIN_HAND,stock);var at=h.absolutePos(support);h.assertTrue(stock.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at).add(0,.5,0),Direction.UP,at,false))).consumesAction(),"Actual native BlockItem places source pillar");h.assertTrue(h.getBlockState(P).getValue(LayeredBlock.AXIS)==Direction.Axis.Z&&stock.getCount()==2,"Original column axis and one genuine material payment");p.setShiftKeyDown(true);at=h.absolutePos(P);h.assertTrue(stock.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at).add(0,.5,0),Direction.UP,at,false))).consumesAction(),"Actual native crouched input places second source pillar");h.assertTrue(h.getBlockState(P.above()).getValue(LayeredBlock.AXIS)==Direction.Axis.Y&&stock.getCount()==1&&!p.hasInfiniteMaterials(),"Real sneak chooses clicked face axis and retains finite original survival stock");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualFeatureRegistryAndNativeCodecPreserveAllEightSourceLayerPatterns(GameTestHelper h){var registry=h.getLevel().registryAccess().lookupOrThrow(Registries.FEATURE);var ops=h.getLevel().registryAccess().createSerializationContext(JsonOps.INSTANCE);var overworld=registry.getOrThrow(AllConfiguredFeatures.STRIATED_ORES_OVERWORLD).value();var nether=registry.getOrThrow(AllConfiguredFeatures.STRIATED_ORES_NETHER).value();h.assertTrue(overworld instanceof LayeredOreFeature&&nether instanceof LayeredOreFeature,"Both real registry values use genuine layered native type");var a=(LayeredOreFeature)overworld;var b=(LayeredOreFeature)nether;h.assertTrue(a.configuration.layerPatterns.size()==6&&b.configuration.layerPatterns.size()==2&&a.configuration.size==32&&b.configuration.size==32&&a.configuration.discardChanceOnAirExposure==0,"Exact original pool counts/size/discard defaults");var expected=new LayeredOreFeature(new LayeredOreConfiguration(List.of(AllLayerPatterns.SCORIA.get(),AllLayerPatterns.CINNABAR.get(),AllLayerPatterns.MAGNETITE.get(),AllLayerPatterns.MALACHITE.get(),AllLayerPatterns.LIMESTONE.get(),AllLayerPatterns.OCHRESTONE.get()),32,0));h.assertTrue(Feature.DIRECT_CODEC.encodeStart(ops,expected).getOrThrow().equals(Feature.DIRECT_CODEC.encodeStart(ops,overworld).getOrThrow()),"Actual native registry data equals every original source layer target, weight, size and order");var encoded=Feature.DIRECT_CODEC.encodeStart(ops,nether).getOrThrow();h.assertTrue(Feature.DIRECT_CODEC.parse(ops,encoded).getOrThrow() instanceof LayeredOreFeature,"Actual native polymorphic feature codec roundtrip");h.assertValueEqual(BuiltInRegistries.FEATURE_TYPE.getKey(a.codec()),Create.asResource("layered_ore"),"Genuine source feature type registration");h.succeed();}
    @GameTest(structure=STRUCTURE) public void realNativeFeaturePlacesInsideActualStoneVolumeWithoutChangingOutsideCells(GameTestHelper h){stoneVolume(h);var outside=P.east(5);h.setBlock(outside,Blocks.DIAMOND_BLOCK);var feature=cinnabar();h.assertTrue(feature.place(h.getLevel(),generator(h),RandomSource.create(224466),h.absolutePos(P)),"Actual native layered Feature.place publishes real matching strata");int replaced=0;for(var pos:BlockPos.betweenClosed(P.offset(-4,-4,-4),P.offset(4,4,4))){var state=h.getBlockState(pos);if(!state.is(Blocks.STONE)){h.assertTrue(state.is(AllBlocks.CRIMSITE)||state.is(AllBlocks.LIMESTONE)||state.is(Blocks.DEEPSLATE)||state.is(Blocks.TUFF),"Only exact source Cinnabar target blocks appear");replaced++;}}h.assertTrue(replaced>0,"Real native section writes occurred");h.assertBlockPresent(Blocks.DIAMOND_BLOCK,outside);h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualNativeLayeredFeatureNeverOverwritesOriginalBlockEntityOrItsSevenNamedItems(GameTestHelper h){stoneVolume(h);h.setBlock(P,Blocks.CHEST);var owner=(ChestBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(P));var stock=new ItemStack(Items.EMERALD,7);stock.set(DataComponents.CUSTOM_NAME,Component.literal("Original generation fixture cargo"));owner.setItem(0,stock);var replacement=new BlockReplacement(new BlockMatchTest(Blocks.CHEST),Blocks.DIAMOND_BLOCK.defaultBlockState());var first=new LayerPattern.Layer(List.of(List.of(replacement)),1,1,1);var second=new LayerPattern.Layer(List.of(List.of(replacement)),1,1,1);var feature=new LayeredOreFeature(new LayeredOreConfiguration(List.of(new LayerPattern(List.of(first,second))),8,0));h.assertFalse(feature.place(h.getLevel(),generator(h),RandomSource.create(886644),h.absolutePos(P)),"Even an explicitly configured chest target cannot overwrite a native owner");h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(P))==owner&&owner.getItem(0)==stock&&stock.getCount()==7&&!owner.isRemoved(),"Actual original BE identity and finite cargo stay owned");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceConfigFilterReallyGatesNativePlacedFeatureAndPreservesDefaultFalse(GameTestHelper h){stoneVolume(h);h.assertFalse(CWorldGen.DEFAULTS.disableWorldGen(),"Pinned disableWorldGen default is false");var placed=new PlacedFeature(Holder.direct(cinnabar()),List.of(ConfigPlacementFilter.INSTANCE));var before=h.getBlockState(P);withConfig(true,()->{h.assertFalse(placed.place(h.getLevel(),generator(h),RandomSource.create(224466),h.absolutePos(P)),"Actual native placement chain observes the real file-backed disable filter");h.assertTrue(h.getBlockState(P)==before,"Disabled native placement leaves exact original state");});withConfig(false,()->h.assertTrue(placed.place(h.getLevel(),generator(h),RandomSource.create(224466),h.absolutePos(P)),"Actual enabled native placement publishes source layers"));var codec=PlacementModifier.CODEC;h.assertTrue(codec.parse(JsonOps.INSTANCE,codec.encodeStart(JsonOps.INSTANCE,ConfigPlacementFilter.INSTANCE).getOrThrow()).getOrThrow()==ConfigPlacementFilter.INSTANCE,"Real registered native config_filter codec resolves original singleton");h.succeed();}
    @GameTest(structure=STRUCTURE) public void malformedLayerDataRejectsZeroProgressBeforeNativeGenerationCanHang(GameTestHelper h){var layer=new JsonObject();layer.addProperty("min_size",0);layer.addProperty("max_size",0);layer.addProperty("weight",1);layer.add("targets",new JsonArray());var pattern=new JsonArray();pattern.add(layer);h.assertTrue(LayerPattern.CODEC.parse(JsonOps.INSTANCE,pattern).error().isPresent(),"Native data codec refuses empty/zero-progress layer plan");var zero=new LayeredOreFeature(new LayeredOreConfiguration(List.of(AllLayerPatterns.CINNABAR.get()),0,0));h.assertFalse(zero.place(h.getLevel(),generator(h),RandomSource.create(4),h.absolutePos(P)),"Original size-zero no-placement result does not enter native generation work");h.succeed();}
}
